from typing import List

class Scaler:
    def __init__(self, numbers: List[float]):
        self.min_val = min(numbers)
        self.max_val = max(numbers)

    def rescale(self, num: float) -> float:
        if self.max_val == self.min_val:
            return 0.0
        return (num - self.min_val) / (self.max_val - self.min_val)


def rescale_to_unit(numbers: List[float]) -> List[float]:
    if len(numbers) < 2:
        raise ValueError("Input list must have at least two elements")
    scaler = Scaler(numbers)
    return [scaler.rescale(num) for num in numbers]

