    def encode(self, s: str) -> str:
        """
        Encodes a string by cycling groups of three characters.
        """
        groups = []
        for i in range(len(s) // 3):
            group = s[3 * i:3 * i + 3]
            if len(group) < 3:
                group += s[3 * i + len(group):3 * i + 3]
            groups.append(group[1:] + group[0])
